package com.jadhavr.erp.email.service;import com.fasterxml.jackson.databind.ObjectMapper;import com.jadhavr.erp.email.config.MailProperties;import com.jadhavr.erp.email.entity.EmailNotification;import com.jadhavr.erp.email.enums.*;import com.jadhavr.erp.email.repository.EmailNotificationRepository;import com.jadhavr.erp.user.entity.User;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.*;import java.util.*;
@Service public class EmailNotificationServiceImpl implements EmailNotificationService{private final EmailNotificationRepository repo;private final MailProperties props;private final ObjectMapper json;private final TemplateDataCipher cipher;private final String frontend;public EmailNotificationServiceImpl(EmailNotificationRepository r,MailProperties p,ObjectMapper j,TemplateDataCipher c,@Value("${app.frontend-url}")String f){repo=r;props=p;json=j;cipher=c;frontend=f;}
@Transactional public void queueUserCreatedEmail(User u){queue(u,EmailType.USER_ACCOUNT_CREATED,"Your Jadhavr ERP account","user-account-created",Map.of("name",u.getFullName(),"url",frontend+"/login"),"USER_CREATED");}@Transactional public void queuePrincipalCreatedEmail(User u){queue(u,EmailType.PRINCIPAL_ACCOUNT_CREATED,"Principal account created","principal-account-created",Map.of("name",u.getFullName(),"college",u.getCollege()==null?"":u.getCollege().getName(),"url",frontend+"/login"),"PRINCIPAL_CREATED");}@Transactional public void queueAccountActivatedEmail(User u){queue(u,EmailType.ACCOUNT_ACTIVATED,"Account activated","account-activated",Map.of("name",u.getFullName(),"url",frontend+"/login"),"ACTIVATED");}@Transactional public void queueAccountDeactivatedEmail(User u){queue(u,EmailType.ACCOUNT_DEACTIVATED,"Account deactivated","account-deactivated",Map.of("name",u.getFullName()),"DEACTIVATED");}@Transactional public void queuePasswordResetEmail(User u,String t,LocalDateTime e){queue(u,EmailType.PASSWORD_RESET,"Reset your password","password-reset",Map.of("name",u.getFullName(),"url",frontend+"/reset-password?token="+t,"expires",e.toString()),"PASSWORD_RESET:"+e);}@Transactional public void queuePasswordChangedEmail(User u){queue(u,EmailType.PASSWORD_CHANGED,"Your password was changed","password-changed",Map.of("name",u.getFullName()),"PASSWORD_CHANGED:"+System.currentTimeMillis());}@Transactional public void queueEmailVerificationEmail(User u,String t,LocalDateTime e){queue(u,EmailType.VERIFY_EMAIL,"Verify your email","verify-email",Map.of("name",u.getFullName(),"url",frontend+"/verify-email?token="+t,"expires",e.toString()),"VERIFY_EMAIL:"+e);}@Transactional public void queueEmailVerifiedEmail(User u){queue(u,EmailType.EMAIL_VERIFIED,"Email verified","email-verified",Map.of("name",u.getFullName()),"EMAIL_VERIFIED");}
private void queue(User u,EmailType type,String subject,String template,Map<String,String>data,String event){String key=event+":"+u.getId()+":"+u.getEmail().toLowerCase();if(repo.existsByIdempotencyKey(key))return;try{EmailNotification n=new EmailNotification();n.setRecipientEmail(u.getEmail());n.setRecipientName(u.getFullName());n.setEmailType(type);n.setSubject(subject);n.setTemplateName(template);n.setTemplateData(cipher.encrypt(json.writeValueAsString(data)));n.setMaxRetries(props.getMaxRetries());n.setCorrelationId(UUID.randomUUID().toString());n.setIdempotencyKey(key);n.setPriority(type==EmailType.PASSWORD_RESET||type==EmailType.VERIFY_EMAIL?EmailPriority.HIGH:EmailPriority.NORMAL);repo.save(n);}catch(Exception e){throw new IllegalStateException("Could not queue email notification",e);}}}

